#include <WiFi.h>

void setup() {
  Serial.begin(115200);

  // Отключаем обычные сервисы, чтобы освободить канал для глушения
  WiFi.disconnect(true);
  WiFi.mode(WIFI_OFF);

  Serial.println("ESP32-S3 Jammer Started");
  Serial.println("Глушение Wi-Fi запущено. Сканер работает непрерывно.");
  Serial.println("Откройте Serial Monitor для просмотра найденных сетей.");

  // Включаем Wi-Fi в режиме Station для активного шума
  WiFi.mode(WIFI_STA);
}

void loop() {
  // 1. Сканирование сетей
  // Это самый быстрый способ получить список доступных сетей
  int numNetworks = WiFi.scanNetworks(false); // false = асинхронное сканирование (быстрее)

  if (numNetworks >= 0) {
    Serial.print("Найдено сетей: ");
    Serial.println(numNetworks);

    for (int i = 0; i < numNetworks; i++) {
      Serial.printf("%d: %s (%d dBm) Ch:%d\n", 
                    i + 1, 
                    WiFi.SSID(i).c_str(), 
                    WiFi.RSSI(i), 
                    WiFi.channel(i));
    }
    Serial.println("------------------");
  } else {
    Serial.println("Ошибка сканирования или нет сетей");
  }

  // 2. Генерация помех (Jamming)
  // Быстрое переключение каналов создает шум, мешающий другим устройствам
  static uint8_t currentChannel = 1;

  // Переключаем канал каждые несколько миллисекунд
  // Чем меньше задержка, тем сильнее помеха, но больше нагрузка на процессор
  WiFi.setChannel(currentChannel);

  // Отправляем пустой пакет или просто держим канал занятым
  // Это создает радиошум на текущем канале

  currentChannel++;
  if (currentChannel > 13) currentChannel = 1;

  // Задержка 1 мс (как просили)
  delay(1);
}
